{
 "procedure": "OPENAI_MATH_CONSTRAINED_PROTOCOL.md section 3.1",
 "selection_sha256": "3dbcd160c970695b570f118352e3c1d348e7653d4846d9a8b53a9f507f7b7f0c",
 "repairs": [],
 "written": [
  {
   "result": "comparingtamedandcompatiblesymplecticconesandcohomologicalpr|Corollary 1.1",
   "ref": "Corollary 1.1",
   "status": "WRITTEN",
   "entry_id": "LZ09-C1.1",
   "source": "T.-J. Li, W. Zhang, Comparing tamed and compatible symplectic cones and cohomological properties of almost complex manifolds, Comm. Anal. Geom. 17(4) (2009) 651-683; read the published version (International Press PDF at the bibliography URL), cross-checked with arXiv:0708.2520v4.",
   "entry": {
    "statement": "Suppose $(M,J)$ is an almost complex $4$-manifold with nonempty $\\mathcal K_J^c$. Then $\\mathcal K_J^t=\\mathcal K_J^c+H_J^{(2,0),(0,2)}(M)_{\\mathbb R}$. In particular, if $b^+(M)=1$, then $\\mathcal K_J^t=\\mathcal K_J^c$. Here $\\mathcal K_J^t=\\{[\\omega]\\in H^2(M;\\mathbb R):\\omega$ symplectic and tamed by $J\\}$, $\\mathcal K_J^c=\\{[\\omega]:\\omega$ compatible with $J\\}$, and $H_J^{(2,0),(0,2)}(M)_{\\mathbb R}$ is the subspace of $H^2(M;\\mathbb R)$ of classes represented by closed real $J$-anti-invariant 2-forms ($C^\\infty$ version, Definition 2.1). It follows from Theorem 1.1 ($J$ $C^\\infty$ full and $\\mathcal K_J^c\\ne\\emptyset$ imply the same equality) and the fact (Draghici-Li-Zhang) that every almost complex structure on a 4-manifold is $C^\\infty$ pure and full.",
    "hypotheses": [
     {
      "text": "M is a closed oriented smooth manifold (paper-wide setting: closed oriented smooth 2n-manifold) and J an almost complex structure compatible with the orientation.",
      "phrases": [
       "closed",
       "compact",
       "almost complex",
       "oriented"
      ],
      "formal": ""
     },
     {
      "text": "M has real dimension 4.",
      "phrases": [
       "4-manifold",
       "four-manifold",
       "dimension 4",
       "almost complex 4-manifold"
      ],
      "formal": "dimM == 4"
     },
     {
      "text": "The J-compatible cone K_J^c is nonempty (J is almost Kaehler).",
      "phrases": [
       "almost k\\\"ahler",
       "compatible symplectic form",
       "nonempty",
       "k_j^c"
      ],
      "formal": ""
     },
     {
      "text": "For the second assertion: b^+(M) = 1.",
      "phrases": [
       "b^+=1",
       "b^+(m)=1",
       "b_2^+=1"
      ],
      "formal": "bplus == 1"
     }
    ],
    "variables": {
     "dimM": "real dimension of M",
     "bplus": "b^+(M), the number of positive eigenvalues of the intersection form on H^2(M;R)"
    },
    "conventions": {
     "tameness": {
      "text": "J tames omega if omega is positive on every J-line span(v,Jv), v nonzero (omega(v,Jv)>0); omega is J-compatible if it is tamed and J-invariant.",
      "fields": {
       "tame_sign": "positive",
       "compatible_requires": "j_invariant"
      }
     },
     "orientation": {
      "text": "Symplectic forms are those compatible with the fixed orientation of M (omega^n a positive volume form), and J is compatible with the given orientation.",
      "fields": {
       "symplectic_orientation": "matching",
       "j_orientation": "matching"
      }
     },
     "grading": {
      "text": "H_J^{(2,0),(0,2)}(M)_R denotes de Rham classes of closed real J-anti-invariant 2-forms (forms, not currents, the 'C^infinity' groups); the current analogues use lower indices.",
      "fields": {
       "anti_invariant_regularity": "smooth",
       "anti_invariant_reality": "real"
      }
     }
    }
   },
   "notes": "Numbering: the published CAG version (read) labels this result Corollary 1.1 (separate counters per environment type); arXiv:0708.2520v4 has the same statement as Corollary 1.4 because there Definition 1.1, Question 1.2, Theorem 1.3 share the counter. The statement is identical in both versions.",
   "writer": "w1",
   "role": "involved",
   "typing_notes": "tame_sign: sign of omega(v,Jv) required for J to tame omega (positive = omega(v,Jv)>0). compatible_requires: extra condition beyond tameness for compatibility (j_invariant = omega J-invariant). symplectic_orientation: whether omega^n agrees with the fixed orientation of M (matching/opposite). j_orientation: whether the orientation induced by J agrees with the fixed orientation (matching/opposite). anti_invariant_regularity: H_J^{(2,0),(0,2)} built from smooth forms (smooth) or currents (current). anti_invariant_reality: real or complex anti-invariant classes."
  },
  {
   "result": "constructingexactlagrangianimmersionswithfewdoublepoints|Lemma 3.2",
   "ref": "Lemma 3.2",
   "status": "WRITTEN",
   "entry_id": "EEMS13-L3.2",
   "source": "T. Ekholm, Y. Eliashberg, E. Murphy, I. Smith, Constructing exact Lagrangian immersions with few double points, Geom. Funct. Anal. 23(6) (2013) 1772-1803; read arXiv:1303.0588v2 (LaTeX source min-intersectYETI-final.tex), Lemma 3.2 = \\label{lm:Leg-Lag-imm}.",
   "entry": {
    "statement": "Let $Y$ be a contact manifold with contact form $\\alpha$, $\\xi=\\ker\\alpha$, and symplectization $(\\mathbb R\\times Y, d(e^s\\alpha))$. Let $f_t\\colon\\Lambda\\to Y$, $t\\in[-1,1]$, be a self-transverse regular Legendrian homotopy, constant near its endpoints, connecting Legendrian embeddings $f_-$ and $f_+$, extended to all $t\\in\\mathbb R$ by $f_t=f_-$ for $t\\le -1$ and $f_t=f_+$ for $t\\ge 1$. Then there exists a self-transverse Lagrangian immersion $G\\colon \\mathbb R\\times\\Lambda\\to\\mathbb R\\times Y$, $G(t,x)=(h(x,t),\\tilde f_t(x))$, such that: (i) there is $T>0$ with $G(t,x)=(t,f_-(x))$ for $t<-T$ and $G(t,x)=(t,f_+(x))$ for $t>T$; (ii) $\\tilde f_t$ is $C^\\infty$-close to $f_t$; (iii) the double points of $G$ are in one-to-one index preserving correspondence with the double points of the regular homotopy $f_t$.",
    "hypotheses": [
     {
      "text": "Y is a contact manifold with a chosen contact form alpha (xi = ker alpha); the target is its symplectization R x Y with form d(e^s alpha).",
      "phrases": [
       "contact manifold",
       "contact form",
       "symplectization",
       "d(e^s\\alpha)"
      ],
      "formal": ""
     },
     {
      "text": "f_t: Lambda -> Y, t in [-1,1], is a self-transverse regular Legendrian homotopy (the immersion (x,t) -> (f_t(x),t) has transverse double points).",
      "phrases": [
       "regular legendrian homotopy",
       "self-transverse",
       "legendrian regular homotopy",
       "transverse self-intersection"
      ],
      "formal": ""
     },
     {
      "text": "The homotopy is constant near its endpoints and its endpoints f_- = f_{-1}, f_+ = f_1 are Legendrian embeddings.",
      "phrases": [
       "constant near its endpoints",
       "legendrian embeddings",
       "connects legendrian embeddings"
      ],
      "formal": ""
     }
    ],
    "variables": {},
    "conventions": {
     "sign": {
      "text": "The index of a double point is the Whitney intersection sign; for a regular homotopy h_t it is computed from the immersion H(x,t)=(h_t(x),t) into Y x [0,1], and for n even and Lambda orientable I({h_t}) = -I({h_{1-t}}), so the direction of the homotopy matters (mod 2 count if n odd or Lambda non-orientable).",
      "fields": {
       "double_point_index": "whitney_sign",
       "homotopy_immersion": "h_t_x_then_t",
       "homotopy_direction": "forward",
       "index_group": "z_if_n_even_and_orientable_else_z2"
      },
      "signs": {
       "reverse_homotopy_index_factor": "-1"
      },
      "params": {
       "n": [
        2,
        40
       ]
      },
      "where": [
       "n % 2 == 0"
      ]
     },
     "normalization": {
      "text": "The symplectization of (Y, alpha) is R x Y with symplectic form d(e^s alpha), s the coordinate on the R-factor, and the first component of G is the R-coordinate.",
      "fields": {
       "symplectization_form": "d_exp_s_alpha",
       "r_coordinate": "first",
       "t_vs_s": "matching"
      }
     },
     "dimension": {
      "text": "Y has dimension 2n-1 and Lambda dimension n-1 (paper-wide notation).",
      "fields": {
       "dim_y": "2n_minus_1",
       "dim_lambda": "n_minus_1"
      }
     }
    }
   },
   "notes": "Numbering checked against arXiv:1303.0588v2: theorem-like environments share one counter per section; Section 3 contains Lemma 3.1 (lm:Leg-Lag, embedded version), Lemma 3.2 (lm:Leg-Lag-imm), Lemma 3.3 (lm:compensation), Lemma 3.4 (lm:near-cone). The lemma itself does not restate a dimension bound; the n>2 assumption in Section 2 is attached to the loose-Legendrian subsection only. The proof reduces to one double point and is given in the paper (not cited externally); the embedded case is attributed to Eliashberg-Gromov, Lemma 4.2.5.",
   "writer": "w1",
   "role": "involved",
   "typing_notes": "double_point_index: index of a double point is the Whitney intersection sign; homotopy_immersion: index of a regular homotopy h_t computed from H(x,t)=(h_t(x),t); homotopy_direction: the lemma uses f_t run from f_- (t=-1) to f_+ (t=1), forward; index_group: signed count in Z for n even and Lambda orientable, Z_2 otherwise; reverse_homotopy_index_factor: I({h_{1-t}}) = -1 * I({h_t}), stated for n even (Lambda orientable); symplectization_form: R x Y with d(e^s alpha); r_coordinate: the first component of G is the R-coordinate s; t_vs_s: the homotopy parameter t increases with the R-coordinate s (G(t,x)=(t,f_-(x)) for t<-T, (t,f_+(x)) for t>T); dim_y / dim_lambda: dim Y = 2n-1, dim Lambda = n-1."
  },
  {
   "result": "constructingexactlagrangianimmersionswithfewdoublepoints|Lemma 3.4",
   "ref": "Lemma 3.4",
   "status": "WRITTEN",
   "entry_id": "EEMS13-L3.4",
   "source": "T. Ekholm, Y. Eliashberg, E. Murphy, I. Smith, Constructing exact Lagrangian immersions with few double points, Geom. Funct. Anal. 23(6) (2013) 1772-1803; read arXiv:1303.0588v2 (LaTeX source min-intersectYETI-final.tex), Lemma 3.4 = \\label{lm:near-cone}.",
   "entry": {
    "statement": "Let $h\\colon\\mathbb R^n\\to\\mathbb R^{2n}_{st}$ be a Lagrangian cone over a Legendrian link $\\phi\\colon S^{n-1}\\to S^{2n-1}_{st}$. Then there exists a Hamiltonian regular homotopy $h_t\\colon\\mathbb R^n\\to\\mathbb R^{2n}_{st}$, $t\\in[0,1]$, with $h_0=h$, fixed near the singularity and outside a ball $B_R\\subset\\mathbb R^n$ of some radius $R>0$ centered at $0$, such that: (1) $h_1$ coincides with the cone over a loose Legendrian knot $\\tilde\\phi$ near $\\partial B_{R/2}$; (2) the immersion $h_1^-:=h_1|_{h_1^{-1}(B_{R/2})}$ has exactly one transverse self-intersection point; (3) if $n=2k$ then, for any $\\phi$, one can arrange $I(h_1^-)=(-1)^{k-1}$, and if in addition $\\phi$ is loose, one can also arrange $I(h_1^-)=(-1)^k$. (Remark 3.5: by scaling, $R$ can be made arbitrarily small.)",
    "hypotheses": [
     {
      "text": "h is a Lagrangian cone: h^{-1}(0)=0 and h(r,x)=(c r^2, phi(x)) in polar coordinates, with phi: S^{n-1} -> S^{2n-1}_st a Legendrian embedding (the link) and c>0.",
      "phrases": [
       "lagrangian cone",
       "legendrian link",
       "cone over a legendrian",
       "conical point"
      ],
      "formal": "c > 0"
     },
     {
      "text": "Ambient: R^{2n}_st with omega_st = sum dx_i ^ dy_i and Liouville form lambda_st = (1/2) sum (x_j dy_j - y_j dx_j); S^{2n-1}_st carries the contact form given by restricting lambda_st.",
      "phrases": [
       "standard symplectic",
       "standard contact structure",
       "unit sphere",
       "liouville form"
      ],
      "formal": ""
     },
     {
      "text": "Looseness of Legendrian knots is used in the sense of Section 2, set up for contact (2n-1)-manifolds with n>2.",
      "phrases": [
       "loose legendrian",
       "n > 2",
       "n\\geq 3",
       "dimension at least"
      ],
      "formal": "n >= 3"
     },
     {
      "text": "For the sign statement (3): n is even, n=2k.",
      "phrases": [
       "n=2k",
       "n is even",
       "even dimension"
      ],
      "formal": "n % 2 == 0"
     },
     {
      "text": "For the option I(h_1^-) = (-1)^k: the link phi is itself a loose Legendrian knot.",
      "phrases": [
       "link is loose",
       "loose legendrian knot",
       "if phi is loose"
      ],
      "formal": ""
     }
    ],
    "variables": {
     "n": "dimension of the Lagrangian (cone R^n in R^{2n})",
     "c": "positive constant in the Lagrangian cone h(r,x)=(c r^2, phi(x))"
    },
    "conventions": {
     "sign": {
      "text": "I(f) is the Whitney self-intersection number: for n even and L orientable the algebraic count of double points with intersection signs in the oriented target (sign of (df(T_{p0}L), df(T_{p1}L)) against the orientation of the ambient space), otherwise the mod 2 count; for an immersion with a conical point it is computed away from the conical point.",
      "fields": {
       "self_intersection_count": "algebraic",
       "intersection_sign_reference": "ambient_orientation",
       "branch_order": "p0_first",
       "conical_point": "excluded"
      },
      "signs": {
       "I_arbitrary_link": "(-1)**(k-1)",
       "I_loose_link": "(-1)**k"
      },
      "params": {
       "k": [
        2,
        20
       ]
      },
      "where": [
       "k >= 2"
      ],
      "cases": {
       "sign_option": [
        "arbitrary phi: I(h_1^-) = (-1)**(k-1)",
        "loose phi (additionally available): I(h_1^-) = (-1)**k"
       ]
      }
     },
     "normalization": {
      "text": "omega_st = sum dx_i ^ dy_i on R^{2n}; contact form alpha_st on S^{2n-1} is the restriction of lambda_st = (1/2) sum (x_j dy_j - y_j dx_j); omega_st = d(r^2 alpha_st) in polar coordinates, and cones are h(r,x)=(c r^2, phi(x)).",
      "fields": {
       "symplectic_form": "sum_dx_wedge_dy",
       "liouville_form": "half_x_dy_minus_y_dx",
       "contact_form": "restricted_liouville",
       "cone_radial_power": "2"
      }
     },
     "hamiltonian": {
      "text": "A Lagrangian regular homotopy f_t is Hamiltonian if the class [iota_{d/dt} F^* omega |_{L x t}] in H^1(L) is independent of t.",
      "fields": {
       "hamiltonian_condition": "constant_flux_class"
      }
     }
    }
   },
   "notes": "Numbering checked against arXiv:1303.0588v2 (Lemma 3.1 lm:Leg-Lag, 3.2 lm:Leg-Lag-imm, 3.3 lm:compensation, 3.4 lm:near-cone, Remark 3.5). The two sign alternatives in (3) are exactly (-1)^{k-1} for arbitrary phi and (-1)^k additionally available when phi is loose; for odd n no sign statement is made. The paper writes 'n>2' explicitly in Section 2.2 (loose Legendrian submanifolds); the lemma statement itself does not repeat it.",
   "writer": "w1",
   "role": "involved",
   "typing_notes": "k: half the dimension, n = 2k (n >= 3 so k >= 2; n <= 40). I_arbitrary_link: Whitney self-intersection number I(h_1^-) achievable for any Legendrian link phi. I_loose_link: the alternative value achievable when phi is loose. self_intersection_count: algebraic (signed, n even, L orientable) vs mod2 count. intersection_sign_reference: double-point sign compares (df(T_p0 L), df(T_p1 L)) with the orientation of the ambient R^{2n}. branch_order: which preimage's tangent plane comes first in the sign comparison. conical_point: whether the conical point is counted (excluded = computed away from it). symplectic_form: omega_st = sum dx_i ^ dy_i. liouville_form: lambda_st = (1/2) sum (x dy - y dx). contact_form: alpha_st is the restriction of lambda_st to S^{2n-1}. cone_radial_power: exponent of r in cone h(r,x) = (c r^power, phi(x)). hamiltonian_condition: regular homotopy is Hamiltonian iff the flux class in H^1(L) is t-independent. Case sign_option is the user's pick between the two achievable values, not a convention."
  },
  {
   "result": "contourlinesofthetwodimensionaldiscretegaussianfreefield|Lemma 3.15",
   "ref": "Lemma 3.15",
   "status": "WRITTEN",
   "entry_id": "SS09-L3.15",
   "source": "O. Schramm and S. Sheffield, Contour lines of the two-dimensional discrete Gaussian free field, Acta Math. 202 (2009) 21-137; read: arXiv:math/0605337v3 LaTeX source (DGFF.tex, April 2008)",
   "entry": {
    "statement": "Lemma 3.15 (Separation). Assume (h), (D) and (S). Let p<1. There is some constant c=c(p,\\bar\\Lambda)>0 such that if R>1/c and v_0 \\notin \\mathfrak B_{6R} \\subset D, then P[ Q(\\Phi_{3R}) \\wedge Q(\\Theta_{2R}) > c | \\Theta_R, \\Phi_{4R}, Z ] > p, provided that P[Z | \\Theta_R, \\Phi_{4R}] > 0. Here \\Phi_R=(D,\\partial_+,h_\\partial,v_0,ext_R\\gamma,ext_R S) is the outer configuration, \\Theta_R=(\\beta_R^s, int_R \\bar S) the inner configuration, Z = {S_\\tau = 0} \\cap {e^*_s \\subset \\gamma} (\\tau the first time the walk S hits \\partial D(\\gamma)), and Q is the 'quality' (separation of strands, normalized by R and capped at 1/100; set to 0 in degenerate cases) defined just before Lemma 3.14.",
    "hypotheses": [
     {
      "text": "(h): D is a bounded domain of R^2 whose boundary is a subgraph of the triangular lattice T; h is the DGFF on D with boundary values h_\\partial on V_\\partial satisfying ||h_\\partial||_\\infty <= \\bar\\Lambda for a fixed constant \\bar\\Lambda>0.",
      "phrases": [
       "discrete gaussian free field",
       "triangular lattice",
       "boundary values bounded by",
       "bounded domain"
      ],
      "formal": ""
     },
     {
      "text": "(D): D is simply connected, \\partial D is a simple closed curve, with two distinct marked midpoints of T-edges x_\\partial, y_\\partial on \\partial D splitting it into arcs \\partial_+ (counterclockwise from x_\\partial to y_\\partial) and \\partial_-.",
      "phrases": [
       "simply connected",
       "simple closed curve",
       "two marked boundary points",
       "dobrushin"
      ],
      "formal": ""
     },
     {
      "text": "(S): \\gamma is the zero-height interface of h from x_\\partial to y_\\partial; v_0 is a T-vertex in D; S is a simple random walk on T started at v_0, independent of h; \\tau is the first time S hits \\partial D(\\gamma).",
      "phrases": [
       "simple random walk",
       "independent of h",
       "zero height interface",
       "first time the walk hits"
      ],
      "formal": ""
     },
     {
      "text": "p < 1 (the constant c depends on p and \\bar\\Lambda).",
      "phrases": [
       "for every p<1",
       "p < 1"
      ],
      "formal": "p < 1"
     },
     {
      "text": "R > 1/c.",
      "phrases": [
       "r sufficiently large",
       "r > 1/c"
      ],
      "formal": "R > 1/c"
     },
     {
      "text": "v_0 \\notin \\mathfrak B_{6R} and \\mathfrak B_{6R} \\subset D, where \\mathfrak B_r is the union of hexagons of the dual hexagonal grid meeting the ball B(0,r).",
      "phrases": [
       "ball of radius 6r contained in d",
       "starting point outside",
       "v_0 not in"
      ],
      "formal": ""
     },
     {
      "text": "P[Z | \\Theta_R, \\Phi_{4R}] > 0 (non-degenerate conditioning).",
      "phrases": [
       "positive probability",
       "provided that"
      ],
      "formal": ""
     }
    ],
    "variables": {
     "p": "target probability level in (.,1)",
     "R": "scale (radius) of the ball around the origin",
     "c": "constant c(p, \\bar\\Lambda) > 0 provided by the lemma"
    },
    "conventions": {
     "normalization": {
      "text": "DGFF density proportional to exp(-sum_{edges {u,v}} (h(v)-h(u))^2/2) on the triangular lattice with unit edge length.",
      "fields": {
       "dgff_energy": "sum_squared_gradient_over_2",
       "lattice": "triangular",
       "edge_length": "1"
      }
     },
     "sign": {
      "text": "Interfaces are oriented so that the positive region D^+ is on their right (clockwise around D^+); \\partial_+ is the counterclockwise arc from x_\\partial to y_\\partial, and e^*_s is oriented consistently with the arc of \\beta from \\hat x to \\hat y.",
      "fields": {
       "interface_orientation": "positive_region_on_right",
       "boundary_arc_plus": "counterclockwise_x_to_y",
       "dual_edge_orientation": "along_beta_x_to_y"
      }
     },
     "indexing": {
      "text": "Numbering as in arXiv:math/0605337v3: Lemma 3.15 is the Separation Lemma (label l.separation) in Section 3.5 'Meeting of random walk and interface'."
     }
    }
   },
   "notes": "Numbering computed from the shared theorem counter within Section 3 of the v3 LaTeX source (3.13 = l.aleq, 3.14 = Compatibility, 3.15 = Separation). The quality functional Q and configurations \\Phi_R, \\Theta_R depend on the setup of Section 3.5 (origin as the special point, edges e_s, \\beta = component of the interface through e^*_s inside \\mathfrak B_R).",
   "writer": "w3",
   "role": "involved",
   "typing_notes": "dgff_energy: DGFF density proportional to exp(-sum over edges (h(v)-h(u))^2/2); lattice: triangular lattice T; edge_length: unit edge length; interface_orientation: interfaces oriented with D^+ on their right (clockwise around D^+); boundary_arc_plus: partial_+ is the counterclockwise arc from x_partial to y_partial; dual_edge_orientation: e^*_s oriented consistently with the arc of beta from hat x to hat y."
  },
  {
   "result": "contourlinesofthetwodimensionaldiscretegaussianfreefield|Lemma 3.24",
   "ref": "Lemma 3.24",
   "status": "WRITTEN",
   "entry_id": "SS09-L3.24",
   "source": "O. Schramm and S. Sheffield, Contour lines of the two-dimensional discrete Gaussian free field, Acta Math. 202 (2009) 21-137; read: arXiv:math/0605337v3 LaTeX source (DGFF.tex, April 2008)",
   "entry": {
    "statement": "Lemma 3.24. Assume (h) and (D). There are constants c>0, \\alpha_3>0, both depending only on \\bar\\Lambda, such that for every \\delta>0, P[ dist(v_0, \\gamma) < \\delta dist(v_0, \\partial D) ] < c \\delta^{\\alpha_3}, where \\gamma is the zero-height interface of the DGFF h from x_\\partial to y_\\partial and v_0 is a vertex of D.",
    "hypotheses": [
     {
      "text": "(h): D is a bounded domain of R^2 whose boundary is a subgraph of the triangular lattice T; h is the DGFF on D with boundary values h_\\partial satisfying ||h_\\partial||_\\infty <= \\bar\\Lambda for a fixed \\bar\\Lambda>0.",
      "phrases": [
       "discrete gaussian free field",
       "triangular lattice",
       "boundary values bounded by",
       "bounded domain"
      ],
      "formal": ""
     },
     {
      "text": "(D): D is simply connected with \\partial D a simple closed curve, and two marked distinct midpoints of T-edges x_\\partial, y_\\partial on \\partial D; \\gamma is the interface from x_\\partial to y_\\partial.",
      "phrases": [
       "simply connected",
       "two marked boundary points",
       "interface from x to y",
       "dobrushin boundary"
      ],
      "formal": ""
     },
     {
      "text": "v_0 is a vertex of T in D (the point from setup (S); the random walk itself plays no role in this lemma, and assumption (\\partial) on the boundary signs is not required).",
      "phrases": [
       "vertex in d",
       "interior point"
      ],
      "formal": ""
     },
     {
      "text": "\\delta > 0 arbitrary.",
      "phrases": [
       "for every delta > 0"
      ],
      "formal": "delta > 0"
     }
    ],
    "variables": {
     "delta": "ratio of the distance threshold to dist(v_0, \\partial D)"
    },
    "conventions": {
     "normalization": {
      "text": "DGFF density proportional to exp(-sum_{edges {u,v}} (h(v)-h(u))^2/2) on the triangular lattice with unit edge length.",
      "fields": {
       "dgff_energy_factor": "half",
       "lattice": "triangular",
       "edge_length": "1"
      }
